import React from 'react';
import { useState, useEffect } from 'react';
import './body.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import productsData from './Products.json'; // Import Products.json

const Body = () => {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    // Instead of fetching, we directly set the products from the imported file
    setProducts(productsData);
  }, []);

  return (
    <div>
      <div className="product-list">
        {products.map((product) => {
          const phoneNumber = '+963982747763';
          const defaultMessage = `I want to know more about ${product.name}`;
          const whatsappLink = `https://wa.me/${phoneNumber}?text=${encodeURIComponent(defaultMessage)}`;
          
          // Use require to dynamically import images
          const image1 = require(`./${product.image1}`);
          const image2 = require(`./${product.image2}`);

          return (
            <div key={product.id} className="product">
              <div className="image-container">
                <img src={image1} alt='laptop' className='image1' />
                <img src={image2} alt='laptop' className='image2' />
              </div>
              <h2>{product.name}</h2>
              <h5>({product.status})</h5>
              <p>{product.details}</p>
              <h3>{product.price}</h3>
              <a href={whatsappLink} className="whatsapp-button">Buy Now</a>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Body;
